CREATE TABLE employees (
  employee_id  NUMBER PRIMARY KEY,
  emp_name     VARCHAR2(30) NOT NULL,
  job_title    VARCHAR2(30),
  manager_id   NUMBER REFERENCES employees (employee_id),
  salary       NUMBER(10)
);

INSERT INTO employees VALUES (1, 'Asha',   'CEO',          NULL, 250000);
INSERT INTO employees VALUES (2, 'Ravi',   'CTO',          1,    180000);
INSERT INTO employees VALUES (3, 'Meera',  'CFO',          1,    170000);
INSERT INTO employees VALUES (4, 'Karan',  'Dev Lead',     2,    120000);
INSERT INTO employees VALUES (5, 'Priya',  'QA Lead',      2,    110000);
INSERT INTO employees VALUES (6, 'Arjun',  'Developer',    4,     80000);
INSERT INTO employees VALUES (7, 'Neha',   'Developer',    4,     75000);
INSERT INTO employees VALUES (8, 'Vikram', 'Accountant',   3,     70000);
COMMIT;

CREATE INDEX emp_manager_ix ON employees (manager_id);

UPDATE employees SET manager_id = 6 WHERE employee_id = 1;

SELECT emp_name, LEVEL
  FROM employees
 START WITH employee_id = 1
CONNECT BY PRIOR employee_id = manager_id;

SELECT TO_CHAR(DATE '2026-10-01' + LEVEL - 1, 'YYYY-MM-DD') AS report_day
  FROM dual
CONNECT BY LEVEL <= 5;
